-- 0059 rental terms bundle and per-booking acceptance (Issue #47, 2026-11-19). Additive only: 0001-0058 unchanged.
-- * rental_terms_bundles keeps each accepted JA/EN text bundle immutably; its SHA-256 is checked against the stored text.
-- * rental_terms_acceptances records, in the booking-creation transaction, which bundle the customer accepted, in which
--   locale, at the database server's time. The refund arithmetic (booking_cancellation_policies, ZAO_CANCELLATION_V1) is
--   separate and untouched; existing bookings get no acceptance row and keep the terms they were sold under.
-- * Authority: TD-adopted draft under the Owner's comprehensive instruction (Issue #47 comment 6984890289). It is not a
--   separate verbatim Owner sign-off or a lawyer review.
CREATE TABLE rental_terms_bundles(
 version text NOT NULL CHECK(version ~ '^ZAO_RENTAL_TERMS_V[0-9]+$'),
 sha256 text NOT NULL CHECK(sha256 ~ '^[0-9a-f]{64}$'),
 canonical text NOT NULL,
 authority text NOT NULL CHECK(length(authority) BETWEEN 1 AND 400),
 effective_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(version),
 UNIQUE(version,sha256),
 CHECK(sha256=encode(sha256(convert_to(canonical,'UTF8')),'hex'))
);
CREATE TRIGGER rental_terms_bundles_immutable BEFORE UPDATE OR DELETE ON rental_terms_bundles FOR EACH ROW EXECUTE FUNCTION pricing_immutable();
CREATE TABLE rental_terms_acceptances(
 booking_id uuid PRIMARY KEY REFERENCES rental_bookings(id),
 version text NOT NULL,
 sha256 text NOT NULL,
 locale text NOT NULL CHECK(locale IN ('ja','en')),
 accepted_at timestamptz NOT NULL DEFAULT now(),
 FOREIGN KEY(version,sha256) REFERENCES rental_terms_bundles(version,sha256)
);
CREATE TRIGGER rental_terms_acceptances_immutable BEFORE UPDATE OR DELETE ON rental_terms_acceptances FOR EACH ROW EXECUTE FUNCTION pricing_immutable();
CREATE FUNCTION booking_record_terms_acceptance() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
BEGIN
 IF jsonb_typeof(NEW.contact->'rentalTerms')='object' THEN
  INSERT INTO rental_terms_acceptances(booking_id,version,sha256,locale,accepted_at)
  VALUES(NEW.id,NEW.contact->'rentalTerms'->>'version',NEW.contact->'rentalTerms'->>'sha256',NEW.contact->'rentalTerms'->>'locale',now());
 END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION booking_record_terms_acceptance() FROM PUBLIC;
CREATE TRIGGER booking_record_terms_acceptance AFTER INSERT ON rental_bookings FOR EACH ROW EXECUTE FUNCTION booking_record_terms_acceptance();
INSERT INTO rental_terms_bundles(version,sha256,canonical,authority) VALUES(
 'ZAO_RENTAL_TERMS_V2',
 '068b727aa7d965ce9e34790d1fa16cde87190656e307bfb874ae7f9b861dee32',
 $terms${"version":"ZAO_RENTAL_TERMS_V2","documents":[{"doc":"terms","locale":"ja","title":"利用規約","sections":[{"heading":"適用","paragraphs":["この規約は、株式会社Yuge（以下「当社」）が運営するスキー・スノーボード用品およびウェアのレンタル予約サービス（以下「本サービス」）の利用に適用します。"]},{"heading":"予約の成立","paragraphs":["予約内容と税込総額を確認画面でご確認のうえお支払いいただき、決済が完了した時点で予約が成立します。"]},{"heading":"料金","paragraphs":["料金は確認画面に表示する消費税込みの総額です。"]},{"heading":"受取・返却","paragraphs":["予約時に選択した店舗で、予約した日時の枠に従って受取・返却してください。貸出期間は2026年12月12日から2027年3月31日までです。","複数日の予約は開始日より後に受け取ることもできますが、返却期限と料金は変わらず、未利用日分の返金はありません。"]},{"heading":"用具の確認と安全","paragraphs":["貸出時に用具の状態を確認してください。使用中に故障、異常、調整の不具合に気付いた場合は、直ちに使用を中止し、店舗へ連絡してください。","スキー・スノーボードには、転倒、衝突、天候や雪面の変化などの危険が伴います。用具を適切に調整しても、すべての事故や負傷を防げるわけではありません。本規約は、当店が法令上負う責任を免除または制限するものではありません。"]},{"heading":"破損・故障・紛失・盗難","paragraphs":["通常の摩耗、経年劣化、製品の不具合など、お客様に責任のない故障について、修理費や補償金は請求しません。","お客様の不適切な使用・管理など、お客様に責任のある原因で用具の破損、紛失または盗難が生じた場合は、原因と損害の状況を確認したうえで、次の範囲で費用をご負担いただきます。","修理できる場合：合理的かつ必要な修理実費。ただし、対象モデルの小売価格の50%を上限とします。請求前に、修理費と上限額の根拠を説明します。","修理できない場合・紛失・盗難の場合：使用年数、状態などを考慮した損害発生時点の用具の時価と、当店に実際に生じた損害額の、いずれか低い額を上限とします。","管理区域外の深雪・樹林等での使用により生じた損傷についても、上記の基準に従って取り扱います。同じ損害について、修理費と補償金を重複して請求することはありません。","請求に先立ち、原因、用具の状態、算定根拠、見積書等を提示して金額を説明します。追加のカード決済は、金額を確認いただき、同意を得たうえで行います。盗難の疑いがある場合は、速やかに警察へ届け出て、店舗にも連絡してください。"]},{"heading":"貸出中の管理","paragraphs":["貸出中の用具は、お客様の責任で適切に管理してください。第三者への転貸・譲渡はできません。盗難、紛失、取り違えを防ぐため、用具の放置を避けてください。"]},{"heading":"キャンセルと返金","paragraphs":["予約した利用開始日時まで48時間以上ある時点でキャンセルを受け付けた場合は、お支払額を全額返金します。ちょうど48時間前のキャンセルも対象です。利用開始日時まで48時間未満となってからのキャンセルは、自動返金の対象外です。個別の事情については店舗へお問い合わせください。","返金の対象となるかどうかは、キャンセルを受け付けた時刻で判定します。その後の処理に時間がかかっても、判定は変わりません。返金は原則としてお支払いに使用したカードへ行い、明細への反映時期はカード会社によって異なります。"]},{"heading":"天候・リフト運休・未使用時間","paragraphs":["利用開始前のキャンセルには、上記の「キャンセルと返金」を適用します。利用開始後、当店が契約どおり用具を提供できる状態にある場合は、天候、リフト運休、利用時間の短縮、未使用時間または早期返却を理由とする返金はありません。","当店が契約どおり用具を提供できない場合や、当店側の責任による不具合等については、この返金除外を適用せず、法令と契約内容に従って対応します。本規約は、法令に基づくお客様の解除・返金その他の権利を制限しません。"]},{"heading":"適用する規約","paragraphs":["予約に適用する規約は、お客様が購入時に確認・同意した版です。改定後の規約を、改定前に成立した予約へ遡って適用することはありません。"]},{"heading":"お問い合わせ","paragraphs":["電話 070-4440-4813　メール rentalstation@yuge-zao.com"]}]},{"doc":"terms","locale":"en","title":"Terms of use","sections":[{"heading":"Scope","paragraphs":["These terms apply to the ski, snowboard and wear rental booking service (the \"Service\") operated by Yuge Co., Ltd. (株式会社Yuge) (\"we\")."]},{"heading":"Booking","paragraphs":["A booking is concluded when you have reviewed the details and the tax-inclusive total on the review screen and the payment has completed."]},{"heading":"Price","paragraphs":["The price is the total including Japanese consumption tax shown on the review screen."]},{"heading":"Pickup and return","paragraphs":["Collect and return the equipment at the store chosen when booking, within the booked time slot. The rental season runs from 12 December 2026 to 31 March 2027.","A multi-day booking may be collected after its start date, but the return deadline and price do not change and unused days are not refunded."]},{"heading":"Equipment checks and safety","paragraphs":["Please check the condition of your equipment when collecting it. If you notice a fault, damage, or a problem with its adjustment during use, stop using it immediately and contact the station.","Skiing and snowboarding involve risks, including falls, collisions, and changes in weather and snow conditions. Even properly adjusted equipment cannot prevent every accident or injury. These terms do not exclude or limit any responsibility we have under applicable law."]},{"heading":"Damage, faults, loss and theft","paragraphs":["We do not charge for normal wear, deterioration with age, product defects, or other equipment faults for which you are not responsible.","If equipment is damaged, lost, or stolen for a reason for which you are responsible, including improper use or care, we will review the cause and circumstances before determining any charge. The following limits apply:","Repairable damage: The reasonable and necessary actual cost of repair, capped at 50% of the model's retail price. We will explain the repair cost and the basis of the cap before requesting payment.","Irreparable damage, loss or theft: The charge will not exceed the lower of the equipment's fair value at the time of the incident, taking its age and condition into account, and our actual loss.","Damage arising from use outside controlled ski areas, including deep snow and wooded areas, is assessed under the same rules. We will not charge both a repair cost and compensation for the same loss.","Before requesting payment, we will explain the cause, the equipment's condition, and how the amount was calculated, with an estimate or other supporting information. Any additional card payment will be made only after you have reviewed and agreed to the amount. If theft is suspected, report it to the police promptly and contact the station."]},{"heading":"Care of equipment","paragraphs":["Please take reasonable care of the equipment throughout the rental period. Do not lend or transfer it to another person. Avoid leaving it unattended to help prevent theft, loss, or mix-ups."]},{"heading":"Cancellation and refunds","paragraphs":["You will receive a full refund if your cancellation is received at least 48 hours before your scheduled rental start. A cancellation received exactly 48 hours before the start is eligible.","Cancellations received less than 48 hours before the scheduled rental start are not eligible for an automatic refund. Please contact the station about individual circumstances.","Eligibility is determined by the time your cancellation is received. Subsequent processing delays do not change that decision. Refunds are normally made to the card used for payment. The time it takes for a refund to appear depends on your card issuer."]},{"heading":"Weather, lift closures and unused rental time","paragraphs":["Cancellations made before the rental starts are subject to the \"Cancellation and refunds\" section above.","Once the rental period has started, no refund is provided for weather, lift closures, a shorter period of use, unused rental time, or early return, provided that we have made the contracted equipment available as agreed.","This exclusion does not apply when we cannot provide the equipment as agreed or when a problem is our responsibility. Such cases are handled in accordance with the contract and applicable law. These terms do not restrict any cancellation, refund, or other rights you have under applicable law."]},{"heading":"Applicable version","paragraphs":["Your booking is governed by the version of the terms you reviewed and accepted at purchase. Revised terms will not be applied retrospectively to bookings completed before the revision."]},{"heading":"Contact","paragraphs":["Tel 070-4440-4813 · Email rentalstation@yuge-zao.com"]}]},{"doc":"cancellation","locale":"ja","title":"キャンセル・返金規定","sections":[{"heading":"オンラインでのキャンセル","paragraphs":["予約はご予約確認ページからキャンセルできます。"]},{"heading":"キャンセルと返金","paragraphs":["予約した利用開始日時まで48時間以上ある時点でキャンセルを受け付けた場合は、お支払額を全額返金します。ちょうど48時間前のキャンセルも対象です。利用開始日時まで48時間未満となってからのキャンセルは、自動返金の対象外です。個別の事情については店舗へお問い合わせください。","返金の対象となるかどうかは、キャンセルを受け付けた時刻で判定します。その後の処理に時間がかかっても、判定は変わりません。返金は原則としてお支払いに使用したカードへ行い、明細への反映時期はカード会社によって異なります。"]},{"heading":"店頭でのご相談","paragraphs":["店頭では、スタッフがご事情を伺い、個別に対応することがあります。"]},{"heading":"お問い合わせ","paragraphs":["株式会社Yuge　電話 070-4440-4813　メール rentalstation@yuge-zao.com"]}]},{"doc":"cancellation","locale":"en","title":"Cancellation and refund policy","sections":[{"heading":"Cancelling online","paragraphs":["You can cancel a booking from your booking page."]},{"heading":"Cancellation and refunds","paragraphs":["You will receive a full refund if your cancellation is received at least 48 hours before your scheduled rental start. A cancellation received exactly 48 hours before the start is eligible.","Cancellations received less than 48 hours before the scheduled rental start are not eligible for an automatic refund. Please contact the station about individual circumstances.","Eligibility is determined by the time your cancellation is received. Subsequent processing delays do not change that decision. Refunds are normally made to the card used for payment. The time it takes for a refund to appear depends on your card issuer."]},{"heading":"At the store","paragraphs":["At the store, our staff may review your circumstances and respond individually."]},{"heading":"Contact","paragraphs":["Yuge Co., Ltd. (株式会社Yuge) · Tel 070-4440-4813 · Email rentalstation@yuge-zao.com"]}]}]}$terms$,
